def format_bytes(n):
    """Return a human-readable byte size.

    Args:
        n (int): Number of bytes.

    Returns:
        str: Human-readable size, e.g., '1.5 KB'.
    """
    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if n < 1024.0:
            return f"{n:.1f} {unit}".replace(".0 ", " ")
        n /= 1024.0
    return f"{n:.1f} PB".replace(".0 ", " ")
